mapper.select:
SELECT a.id, a.user_id AS userId, u.username AS username, a.module, a.action, a.target_type AS targetType, a.target_id AS targetId, a.detail, a.occurred_at AS occurredAt FROM audit_trail a LEFT JOIN sys_user u ON a.user_id = u.id
a.user_id = #{userId}
AND a.module = #{module}
AND a.action = #{action}
ORDER BY a.occurred_at DESC, a.id DESC
